-- PELEX UPDATE (26 Oct). Apply after groups.sql; requires existing bot_plans, businesses and pitch_profiles.
create or replace function public.my_rooms() returns jsonb language sql security definer stable set search_path=public as $$ select coalesce(jsonb_agg(q.x order by q.x->>'last_at' desc),'[]'::jsonb) from(select jsonb_build_object('id',r.id,'name',r.name,'emoji',r.emoji,'room_code',r.room_code,'role',m.role,'invite_token',r.invite_token,'members',(select count(*) from room_members mm where mm.room_id=r.id),'last_id',coalesce((select max(g.id) from room_messages g where g.room_id=r.id),0),'last_at',coalesce((select max(g.created_at) from room_messages g where g.room_id=r.id),r.created_at)) as x from room_members m join rooms r on r.id=m.room_id where m.user_id=auth.uid()) q; $$;
create table if not exists public.tester_emails(email text primary key); alter table public.tester_emails enable row level security; revoke all on public.tester_emails from anon,authenticated;
create or replace function public.start_test_plan(p_kind text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); em text:=lower(coalesce(auth.jwt()->>'email','')); begin if uid is null then raise exception 'Please sign in first.'; end if; if p_kind not in('personal','business','pitch') then raise exception 'Unknown plan.'; end if; if not exists(select 1 from tester_emails t where lower(t.email)=em) then raise exception 'Paid plans are not open yet. Payments are coming soon, and testers can switch plans on early.'; end if; insert into bot_plans(user_id,kind,active,paid_until) values(uid,p_kind,true,now()+interval '30 days') on conflict(user_id,kind) do update set active=true,paid_until=excluded.paid_until; if p_kind='pitch' then insert into pitch_profiles(user_id,plan_active) values(uid,true) on conflict(user_id) do update set plan_active=true; end if; return jsonb_build_object('kind',p_kind,'active',true); end $$;
create unique index if not exists businesses_one_per_owner on public.businesses(owner_id);
create or replace function public.my_business() returns jsonb language sql security definer stable set search_path=public as $$ select to_jsonb(x) from(select id,name,tone,description,website,limits,active from public.businesses where owner_id=auth.uid() limit 1) x; $$;
create or replace function public.save_business(p_name text,p_tone text,p_description text,p_website text,p_limits text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); bid uuid; nm text:=left(trim(coalesce(p_name,'')),80); site text:=left(trim(coalesce(p_website,'')),300); begin if uid is null then raise exception 'Please sign in first.'; end if; if not exists(select 1 from bot_plans where user_id=uid and kind='business' and active) then raise exception 'Start the Business Bot plan first.'; end if; if length(nm)<1 then raise exception 'Enter your business name.'; end if; if site<>'' and site !~* '^https?://' then raise exception 'The website must start with http:// or https://'; end if; select id into bid from businesses where owner_id=uid; if bid is null then insert into businesses(owner_id,name,tone,description,website,limits,active) values(uid,nm,left(coalesce(p_tone,''),80),left(coalesce(p_description,''),3000),site,left(coalesce(p_limits,''),2000),true) returning id into bid; else update businesses set name=nm,tone=left(coalesce(p_tone,''),80),description=left(coalesce(p_description,''),3000),website=site,limits=left(coalesce(p_limits,''),2000),active=true where id=bid; end if; return jsonb_build_object('id',bid,'name',nm); end $$;
create table if not exists public.support_staff(user_id uuid primary key references auth.users(id) on delete cascade,added_at timestamptz not null default now()); alter table public.support_staff enable row level security; revoke all on public.support_staff from anon,authenticated;
create or replace function public.is_support() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from public.support_staff where user_id=auth.uid()); $$;
create or replace function public.support_open_requests() returns jsonb language plpgsql security definer set search_path=public as $$ begin if not is_support() then raise exception 'Support access only.'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'room_id',s.room_id,'room_name',r.name,'room_code',r.room_code,'emoji',r.emoji,'status',s.status,'by',p.first_name,'note',s.note,'created_at',s.created_at) order by s.created_at desc) from support_requests s join rooms r on r.id=s.room_id left join member_profiles p on p.user_id=s.requested_by where s.status in('open','joined')),'[]'::jsonb); end $$;
create or replace function public.support_messages(p_room uuid,p_after bigint default 0) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not is_support() then raise exception 'Support access only.'; end if; if not exists(select 1 from support_requests where room_id=p_room and status in('open','joined')) then raise exception 'There is no open support request for this group.'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'user_id',m.user_id,'kind',m.kind,'content',m.content,'created_at',m.created_at,'first_name',p.first_name,'emoji',p.emoji) order by m.id) from room_messages m left join member_profiles p on p.user_id=m.user_id where m.room_id=p_room and m.id>greatest(coalesce(p_after,0),(select coalesce(max(x.id),0)-300 from room_messages x where x.room_id=p_room))),'[]'::jsonb); end $$;
create or replace function public.support_post(p_room uuid,p_text text) returns void language plpgsql security definer set search_path=public as $$ declare t text:=left(trim(coalesce(p_text,'')),4000); st text; begin if not is_support() then raise exception 'Support access only.'; end if; if length(t)<1 then return; end if; select status into st from support_requests where room_id=p_room and status in('open','joined') order by created_at desc limit 1; if not found then raise exception 'There is no open support request for this group.'; end if; if st='open' then update support_requests set status='joined' where room_id=p_room and status='open'; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system','Pelex Support joined the chat.'); end if; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'pelex',t); end $$;
create or replace function public.support_close(p_room uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not is_support() then raise exception 'Support access only.'; end if; update support_requests set status='closed' where room_id=p_room and status in('open','joined'); update rooms set pelex_called_at=null where id=p_room; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system','Pelex Support has left the group.'); end $$;
revoke execute on function public.start_test_plan(text),public.my_business(),public.save_business(text,text,text,text,text),public.is_support(),public.support_open_requests(),public.support_messages(uuid,bigint),public.support_post(uuid,text),public.support_close(uuid) from public,anon;
grant execute on function public.start_test_plan(text),public.my_business(),public.save_business(text,text,text,text,text),public.is_support(),public.support_open_requests(),public.support_messages(uuid,bigint),public.support_post(uuid,text),public.support_close(uuid) to authenticated;
